<?php require __DIR__.'/includes/bootstrap.php';$id=(string)($_GET['id']??'');$product=shop_product($id);if(!$product){http_response_code(404);} ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $product?shop_e($product['name']).' | Travel Shop':'Product not found | Travel Shop' ?></title><meta name="description" content="<?= $product?shop_e($product['short_description']):'Product not found' ?>"><link rel="stylesheet" href="/shop/assets/css/shop.css"></head><body><?php require __DIR__.'/includes/header.php'; ?>
<?php if(!$product): ?><h1>Product not found</h1><p><a href="/shop/products.php">Return to products</a></p><?php else:?><p class="sample-banner">Sample product only — not currently available for purchase.</p><article><div class="product-layout"><div><img class="product-image" src="<?= shop_e($product['main_image']) ?>" alt="<?= shop_e($product['name']) ?>"><script type="application/ld+json"><?= json_encode(['@context'=>'https://schema.org','@type'=>'Product','name'=>$product['name'],'description'=>$product['full_description'],'sku'=>$product['sku'],'image'=>'https://'.($_SERVER['HTTP_HOST']??'example.com').$product['main_image'],'offers'=>['@type'=>'Offer','priceCurrency'=>'KES','price'=>(float)$product['price'],'availability'=>$product['stock']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock']],JSON_UNESCAPED_SLASHES) ?></script></div><div><h1><?= shop_e($product['name']) ?></h1><p class="price"><?= shop_money($product['price']) ?> <small>KES</small></p><p><?= nl2br(shop_e($product['full_description'])) ?></p><p><strong>SKU:</strong> <?= shop_e($product['sku']) ?></p><p><strong>Size / weight:</strong> <?= shop_e($product['weight_size']) ?></p><p class="stock">Available quantity: <?= (int)$product['stock'] ?></p><p><strong>Physical item:</strong> Artefact or trinket. Shipping is based on the delivery method selected at checkout. Pickup may be available by arrangement.</p><?php if($product['stock']>0):?><form method="post" action="/shop/cart.php" class="quantity-row"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?= shop_e($product['id']) ?>"><label>Quantity<input id="quantity" name="quantity" type="number" min="1" max="<?= (int)$product['stock'] ?>" value="1"></label><button class="shop-button" type="submit">Add to cart</button></form><?php else:?><p class="stock out">Out of stock</p><?php endif;?></div></div><h2 class="shop-section-title">Related products</h2><div class="shop-grid"><?php foreach(array_filter(shop_catalog(),fn($p)=>$p['id']!==$product['id']) as $related):?><article class="product-card"><a href="/shop/product.php?id=<?= urlencode($related['id']) ?>"><img src="<?= shop_e($related['main_image']) ?>" alt="<?= shop_e($related['name']) ?>" loading="lazy"></a><div class="product-card-body"><h3><?= shop_e($related['name']) ?></h3><p class="price"><?= shop_money($related['price']) ?></p></div></article><?php endforeach;?></div></article><?php endif;?><?php require __DIR__.'/includes/footer.php'; ?></body></html>
